    """Merge two sorted lists into one sorted list (duplicates are kept)."""
    if not a:
        return b
    if not b:
        return a

    merged = []
    i, j = 0, 0

    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1

    merged.extend(a[i:])
    merged.extend(b[j:])

    return merged
